            output[r][line_idx] = 2

    if len(object_pixels) == 1:
        r_obj, c_obj = object_pixels[0]
        if line_type == 'h':
            if r_obj > line_idx:
                target_r = line_idx + 1
                for c in range(cols):
                    output[target_r][c] = grid[r_obj][c_obj]
                if line_idx + 2 < rows:
                    for c in range(cols):
                        output[line_idx + 2][c] = 8
            else:
                target_r = line_idx - 1
                for c in range(cols):
                    output[target_r][c] = grid[r_obj][c_obj]
                if line_idx - 2 >= 0:
                    for c in range(cols):
                        output[line_idx - 2][c] = 8
        else:
            if c_obj > line_idx:
                target_c = line_idx + 1
                for r in range(rows):
                    output[r][target_c] = grid[r_obj][c_obj]
                if line_idx + 2 < cols:
                    for r in range(rows):
                        output[r][line_idx + 2] = 8
            else:
                target_c = line_idx - 1
                for r in range(rows):
                    output[r][target_c] = grid[r_obj][c_obj]
                if line_idx - 2 >= 0:
                    for r in range(rows):
                        output[r][line_idx - 2] = 8
    else:
        for r, c in object_pixels:
            output[r][c] = grid[r][c]

        if line_type == 'h':
            min_r = min(p[0] for p in object_pixels)
            max_r = max(p[0] for p in object_pixels)
            if min_r > line_idx:
                r8s = max_r + 1
            else:
                r8s = min_r - 1
            if 0 <= r8s < rows:
